<script setup lang="ts">
import{ref,watch}from'vue'
import{api,send}from'../api'
import{useCms}from'../store'
import{useQuasar}from'quasar'
import{t,appLocale}from'../i18n'
const props=defineProps<{orders?:boolean}>(),cms=useCms(),q=useQuasar(),rows=ref<any[]>([]),page=ref(1),next=ref(false),error=ref(''),editing=ref<any>(null),saving=ref(false),price=ref('')
const money=(n:number,c:string)=>new Intl.NumberFormat(appLocale.value,{style:'currency',currency:c}).format(n/100)
async function load(){if(!cms.selectedId)return;try{error.value='';const r=await api<any>(`/websites/${cms.selectedId}/${props.orders?'orders':'products'}?page=${page.value}`);rows.value=r.data;next.value=!!r.next_page_url}catch(e:any){error.value=e.message}}
watch([()=>cms.selectedId,()=>props.orders],()=>{page.value=1;editing.value=null;load()},{immediate:true})
function edit(p?:any){editing.value=p?JSON.parse(JSON.stringify(p)):{name:'',sku:'',description:'',image:'',currency:cms.selected?.default_currency||'USD',price_minor:100,stock:0,active:false};editing.value.active=!!editing.value.active;price.value=(editing.value.price_minor/100).toFixed(2)}
async function save(){if(!/^\d+(\.\d{1,2})?$/.test(price.value)){q.notify({type:'negative',message:t('Enter a price with at most two decimal places.')});return}saving.value=true;try{const p=editing.value;await api(`/websites/${cms.selectedId}/products${p.id?'/'+p.id:''}`,send(p.id?'PUT':'POST',{...p,price_minor:Math.round(Number(price.value)*100)}));editing.value=null;await load()}catch(e:any){q.notify({type:'negative',message:t(e.message)})}finally{saving.value=false}}
async function update(o:any,status:string,payment:string){saving.value=true;try{await api(`/websites/${cms.selectedId}/orders/${o.id}`,send('PUT',{status,payment_status:payment,expected_status:o.status,expected_payment_status:o.payment_status}));await load()}catch(e:any){q.notify({type:'negative',message:t(e.message)})}finally{saving.value=false}}
function paid(o:any){q.dialog({title:t('Confirm payment received'),message:t('Only mark paid after verifying the payment outside this system.'),cancel:true}).onOk(()=>update(o,o.status,'paid'))}
function cancel(o:any){q.dialog({title:t('Cancel this order?'),message:t('Stock will be restored once. Paid orders cannot be cancelled here.'),cancel:true}).onOk(()=>update(o,'cancelled',o.payment_status))}
</script>
<template><section class="panel"><div class="action-row"><h2>{{ $t(orders?'Orders':'Products') }}</h2><button v-if="!orders" class="btn primary" @click="edit()">{{ $t('Add product') }}</button></div><p>{{ $t(orders?'Cash on delivery orders. Payment recording is manual; no card gateway is connected.':'Prices use the website currency. Archive a product by turning off Active. Stock is reserved at checkout.') }}</p><p v-if="error" role="alert">{{ $t(error) }}</p><p v-if="!rows.length">{{ $t('No records yet.') }}</p><div v-if="!orders" class="table-scroll"><table class="commerce-table"><thead><tr><th>{{ $t('Product') }}</th><th>SKU</th><th>{{ $t('Price') }}</th><th>{{ $t('Stock') }}</th><th>{{ $t('Status') }}</th><th>{{ $t('Actions') }}</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td>{{ p.name }}</td><td>{{ p.sku }}</td><td>{{ money(p.price_minor,p.currency) }}</td><td>{{ p.stock }}</td><td>{{ $t(p.active?'Active':'Archived') }}</td><td><button class="text-link" @click="edit(p)">{{ $t('Edit') }}</button></td></tr></tbody></table></div><article v-else v-for="o in rows" :key="o.id" class="inbox-message"><header><strong>{{ o.reference }}</strong><span>{{ money(o.total_minor,o.currency) }}</span></header><p>{{ o.name }} · {{ o.email }} · {{ o.phone }}</p><p class="preserve-text">{{ o.address }}</p><ul><li v-for="i in o.items" :key="i.product_id">{{ i.name }} × {{ i.quantity }} · {{ money(i.price_minor,o.currency) }}</li></ul><div class="action-row"><span>{{ $t(o.status) }} · {{ $t(o.payment_status) }}</span><button v-if="o.status==='pending'" class="btn secondary" :disabled="saving" @click="update(o,'confirmed',o.payment_status)">{{ $t('Confirm order') }}</button><button v-if="o.status==='confirmed'" class="btn secondary" :disabled="saving" @click="update(o,'fulfilled',o.payment_status)">{{ $t('Mark fulfilled') }}</button><button v-if="o.payment_status==='unpaid'&&o.status!=='cancelled'" class="btn secondary" :disabled="saving" @click="paid(o)">{{ $t('Record payment') }}</button><button v-if="['pending','confirmed'].includes(o.status)&&o.payment_status==='unpaid'" class="text-link danger" :disabled="saving" @click="cancel(o)">{{ $t('Cancel order') }}</button></div></article><div class="action-row"><button class="btn secondary" :disabled="page===1" @click="page--;load()">{{ $t('Previous') }}</button><span>{{ page }}</span><button class="btn secondary" :disabled="!next" @click="page++;load()">{{ $t('Next') }}</button></div></section><q-dialog :model-value="!!editing" @hide="editing=null" persistent><q-card v-if="editing" style="width:560px;max-width:95vw"><q-card-section><h3>{{ $t('Product details') }}</h3><form class="commerce-editor" @submit.prevent="save"><q-input outlined v-model="editing.name" :label="$t('Name')" required maxlength="190"/><q-input outlined v-model="editing.sku" label="SKU" required maxlength="80"/><q-input outlined v-model="editing.description" :label="$t('Description')" type="textarea" maxlength="10000"/><q-input outlined v-model="editing.image" :label="$t('Image URL')"/><q-select emit-value map-options outlined v-model="editing.currency" :options="$translatedOptions([cms.selected?.default_currency])" :label="$t('Currency')"/><q-input outlined v-model="price" :label="$t('Price')+' · '+editing.currency" inputmode="decimal" required/><q-input outlined v-model.number="editing.stock" :label="$t('Stock')" type="number" min="0" max="1000000" step="1" required/><q-checkbox v-model="editing.active" :label="$t('Active')"/><div class="dialog-footer"><q-btn flat :label="$t('Cancel')" :disable="saving" @click="editing=null"/><q-btn type="submit" color="primary" :label="$t('Save product')" :loading="saving"/></div></form></q-card-section></q-card></q-dialog></template>
